    #include <stdio.h>

// Returns count of all squares
// in a rectangle of size m x n
int countSquares(int m, int n) {
    // If n is smaller, swap m and n
    if (n < m) {
        int temp = m;
        m = n;
        n = temp;
    }

    // Now n is greater dimension,
    // apply formula
    return (m * (m + 1) * (2 * m + 1)) / 6 + ((n - m) * m * (m + 1)) / 2;
}

int main() {
    int m = 4, n = 3;
    printf("%d", countSquares(m, n));
    return 0;
}


